#include "pdc_os_descriptors.h"
#include "pdc_common.h"
#include <string.h>

/* Same UUID as psp_winusb_probe.INTERFACE_GUID, generated by the build. */
#include "pdc_identity.h"

static void le16(uint8_t *p, unsigned n) { p[0]=(uint8_t)n; p[1]=(uint8_t)(n>>8); }
static void le32(uint8_t *p, uint32_t n) {
    p[0]=(uint8_t)n;p[1]=(uint8_t)(n>>8);p[2]=(uint8_t)(n>>16);p[3]=(uint8_t)(n>>24);
}
static size_t utf16(uint8_t *p, const char *s) {
    size_t i=0;
    do { p[i*2]=(uint8_t)s[i];p[i*2+1]=0; } while(s[i++]);
    return i*2;
}
size_t pdc_os_string(uint8_t *out, size_t cap) {
    static const uint8_t value[18]={18,3,'M',0,'S',0,'F',0,'T',0,'1',0,'0',0,'0',0,
                                    PDC_OS_VENDOR_REQUEST,0};
    if(cap<sizeof(value))return 0;
    memcpy(out,value,sizeof(value));return sizeof(value);
}
size_t pdc_os_compatible(uint8_t *out, size_t cap) {
    if(cap<40)return 0;
    memset(out,0,40);le32(out,40);le16(out+4,0x0100);le16(out+6,4);
    out[8]=1; /* one WinUSB function, NOT both interfaces */
    out[16]=PDC_USB_INTERFACE;out[17]=1;
    memcpy(out+18,"WINUSB",6);return 40;
}
size_t pdc_os_properties(uint8_t *out, size_t cap) {
    static const char name[]="DeviceInterfaceGUIDs";
    static const char guid[]=PDC_INTERFACE_GUID;
    size_t name_bytes=sizeof(name)*2;
    size_t data_bytes=sizeof(guid)*2+2; /* REG_MULTI_SZ double-NUL */
    size_t property=4+4+2+name_bytes+4+data_bytes;
    size_t total=10+property;
    uint8_t *p;
    if(cap<total || total>0xffff)return 0;
    memset(out,0,total);le32(out,(uint32_t)total);
    le16(out+4,0x0100);le16(out+6,5);le16(out+8,1);
    p=out+10;le32(p,(uint32_t)property);le32(p+4,7); /* REG_MULTI_SZ */
    le16(p+8,(unsigned)name_bytes);utf16(p+10,name);
    le32(p+10+name_bytes,(uint32_t)data_bytes);
    utf16(p+14+name_bytes,guid);
    return total;
}
size_t pdc_os_control(uint8_t type, uint8_t req, uint16_t value,
                      uint16_t index, uint16_t requested,
                      uint8_t *out, size_t cap) {
    size_t n=0;
    if(type==0x80 && req==6 && value==0x03ee)
        n=pdc_os_string(out,cap);
    else if(type==0xc0 && req==PDC_OS_VENDOR_REQUEST && value==0 && index==4)
        n=pdc_os_compatible(out,cap);
    else if(type==0xc1 && req==PDC_OS_VENDOR_REQUEST &&
            value==PDC_USB_INTERFACE && index==5)
        n=pdc_os_properties(out,cap);
    if(n>requested)n=requested;
    return n;
}
